import { test, expect } from '@playwright/test';

test('cache isolation: private data is not shared across sessions', async ({ browser }) => {
  const baseUrl = process.env.STACKFOLD_CACHE_BASE_URL || "http://127.0.0.1:4178";
  const sessionA = await browser.newContext({
    extraHTTPHeaders: { "x-stackfold-test-session": process.env.STACKFOLD_SESSION_A! },
  });
  const sessionB = await browser.newContext({
    extraHTTPHeaders: { "x-stackfold-test-session": process.env.STACKFOLD_SESSION_B! },
  });

  // HTML dashboard (html)
  const warmprivate_html = await sessionA.request.get(baseUrl + "/dashboard");
  expect(warmprivate_html.ok()).toBeTruthy();
  const checkprivate_html = await sessionB.request.get(baseUrl + "/dashboard");
  expect(checkprivate_html.ok()).toBeTruthy();
  await expect(checkprivate_html.text()).resolves.not.toContain(process.env.STACKFOLD_MARKER_A!);

  // JSON identity endpoint (json)
  const warmprivate_json = await sessionA.request.get(baseUrl + "/api/me");
  expect(warmprivate_json.ok()).toBeTruthy();
  const checkprivate_json = await sessionB.request.get(baseUrl + "/api/me");
  expect(checkprivate_json.ok()).toBeTruthy();
  await expect(checkprivate_json.text()).resolves.not.toContain(process.env.STACKFOLD_MARKER_A!);

  // Production build route (production_build)
  const warmproduction_build = await sessionA.request.get(baseUrl + "/production/dashboard");
  expect(warmproduction_build.ok()).toBeTruthy();
  const checkproduction_build = await sessionB.request.get(baseUrl + "/production/dashboard");
  expect(checkproduction_build.ok()).toBeTruthy();
  await expect(checkproduction_build.text()).resolves.not.toContain(process.env.STACKFOLD_MARKER_A!);

  await sessionA.close();
  await sessionB.close();
});
